-- HG shared platform migration (schema: lms)
-- Source: lms-hg/supabase/migrations/20260824000000_cloud_legacy_policy_cleanup.sql
-- Generated by platform/tools/convert.py: references to the public schema were
-- rewritten to `lms`; private schemas renamed app_private -> lms_private.
-- Edit the source app's migration history only until the cutover; after that, edit here.

SET search_path TO lms, extensions;

-- Cloud compatibility hardening for legacy policies that predate the
-- canonical RLS matrix. PostgreSQL permissive policies are OR-combined, so
-- leaving these policies in place would weaken the policies introduced by
-- 20260823001000_database_truth_rls_matrix.sql.

-- learner_progress: remove historical direct mutation paths. The canonical
-- matrix permits learners to update only the notes column through its active
-- user policy; starting/completion remain trusted server operations.
DROP POLICY IF EXISTS "progress: learner insert own" ON lms.learner_progress;
DROP POLICY IF EXISTS "progress: learner update own" ON lms.learner_progress;

-- activity_logs: writes now go through log_activity_for_user(...).
DROP POLICY IF EXISTS "activity_logs: user insert own" ON lms.activity_logs;

-- module_versions: the old policy exposed any current version even when its
-- module was unpublished. The canonical policy also checks module visibility
-- and active-user status.
DROP POLICY IF EXISTS "module_versions: learner read current" ON lms.module_versions;

-- whatsapp_logs: direct authenticated writes are not part of the canonical
-- permission model, and the historical read policy did not enforce active-user
-- status.
DROP POLICY IF EXISTS "whatsapp_logs: user insert own" ON lms.whatsapp_logs;
DROP POLICY IF EXISTS "whatsapp_logs: user update own" ON lms.whatsapp_logs;
DROP POLICY IF EXISTS "whatsapp_logs: user read own" ON lms.whatsapp_logs;

-- categories: replace unconditional authenticated reads with the active-user
-- policy created by the canonical matrix.
DROP POLICY IF EXISTS "categories: read all" ON lms.categories;

-- Storage: remove historical permissive study-note access. These policies
-- would otherwise OR with the resource-authorized current-version policy.
DROP POLICY IF EXISTS "Users can view study notes" ON storage.objects;
DROP POLICY IF EXISTS "Admins can upload study notes" ON storage.objects;
DROP POLICY IF EXISTS "Authenticated users can view module files" ON storage.objects;

-- module-files is unused by the current application and contains no objects in
-- the production project. Keep the bucket for compatibility, but make it
-- private so future objects cannot accidentally become public by bucket flag.
UPDATE storage.buckets
SET public = FALSE
WHERE id = 'module-files';
